-- Provisional retention inventory, NOT an approved retention schedule.
-- Unknown periods are pending approval, never justified indefinite retention.
-- No retained-data release path is enabled by this migration.
CREATE TABLE identity.data_retention_records (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 user_id uuid NOT NULL REFERENCES identity.users(id) ON DELETE RESTRICT,
 deletion_record_id uuid NOT NULL REFERENCES identity.account_deletion_records(id) ON DELETE RESTRICT,
 retained_data_type text NOT NULL,
 classification text NOT NULL, disposition text NOT NULL, legal_or_safety_reason text NOT NULL,
 access_policy text NOT NULL CHECK(access_policy IN('purpose_restricted','reference_only')),
 policy_status text NOT NULL CHECK(policy_status IN('pending_approval','not_applicable')),
 retention_expires_at timestamptz, indefinite_reason text, deleted_at timestamptz,
 observed_present boolean, registry_hash text NOT NULL CHECK(registry_hash~'^[0-9a-f]{64}$'),
 created_at timestamptz NOT NULL, audit_id uuid NOT NULL UNIQUE REFERENCES platform.audit_logs(id) ON DELETE RESTRICT,
 lease_owner uuid NOT NULL, lease_generation integer NOT NULL CHECK(lease_generation>0),
 lease_expires_at timestamptz NOT NULL, transaction_id text NOT NULL,
 UNIQUE(deletion_record_id,retained_data_type),
 CHECK(retention_expires_at IS NULL AND indefinite_reason IS NULL AND deleted_at IS NULL)
);
