,"nullable":false},{"name":"support_thread_id","type":"uuid","nullable":false},{"name":"sender_type","type":"text","nullable":false},{"name":"sender_user_id","type":"uuid","nullable":true},{"name":"sender_admin_id","type":"uuid","nullable":true},{"name":"message_text","type":"text","nullable":false},{"name":"command_id","type":"uuid","nullable":false},{"name":"request_id","type":"uuid","nullable":false},{"name":"request_digest","type":"text","nullable":false},{"name":"idempotency_key","type":"text","nullable":false},{"name":"thread_version_after","type":"integer","nullable":false},{"name":"unanswered_user_messages_after","type":"integer","nullable":false},{"name":"created_at","type":"timestamp with time zone","nullable":false}],"foreignKeys":[{"target":"administration.admin_users","definition":"FOREIGN KEY (sender_admin_id) REFERENCES administration.admin_users(id) ON DELETE RESTRICT"},{"target":"identity.users","definition":"FOREIGN KEY (sender_user_id) REFERENCES identity.users(id) ON DELETE RESTRICT"},{"target":"support.support_threads","definition":"FOREIGN KEY (support_thread_id) REFERENCES support.support_threads(id) ON DELETE RESTRICT"}]},{"table":"support.support_threads","columns":[{"name":"id","type":"uuid","nullable":false},{"name":"user_id","type":"uuid","nullable":false},{"name":"status","type":"text","nullable":false},{"name":"open_command_id","type":"uuid","nullable":false},{"name":"open_idempotency_key","type":"text","nullable":false},{"name":"open_request_digest","type":"text","nullable":false},{"name":"last_message_at","type":"timestamp with time zone","nullable":false},{"name":"created_at","type":"timestamp with time zone","nullable":false},{"name":"closed_at","type":"timestamp with time zone","nullable":true},{"name":"version","type":"integer","nullable":false},{"name":"product_epoch","type":"integer","nullable":false}],"foreignKeys":[{"target":"identity.users","definition":"FOREIGN KEY (user_id) REFERENCES identity.users(id) ON DELETE RESTRICT"}]}]$registry$::jsonb $function$;
CREATE FUNCTION identity.retention_registry_hash() RETURNS text LANGUAGE sql IMMUTABLE AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object('descriptors',identity.retention_descriptors(),'schema',identity.retention_schema())::text,'UTF8')),'hex') $$;
CREATE FUNCTION identity.retention_catalog_valid() RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE old_path text:=current_setting('search_path'); actual jsonb;
BEGIN
 PERFORM set_config('search_path','pg_catalog',true);
 SELECT jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,
  'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull) ORDER BY a.attnum)
    FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
  'foreignKeys',coalesce((SELECT jsonb_agg(jsonb_build_object('target',rn.nspname||'.'||rc.relname,'definition',pg_get_constraintdef(con.oid)) ORDER BY pg_get_constraintdef(con.oid))
    FROM pg_constraint con JOIN pg_class rc ON rc.oid=con.confrelid JOIN pg_namespace rn ON rn.oid=rc.relnamespace WHERE con.conrelid=c.oid AND con.contype='f'),'[]'::jsonb)) ORDER BY n.nspname,c.relname)
 INTO actual FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE c.relkind IN('r','p') AND n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema';
 PERFORM set_config('search_path',old_path,true);
 RETURN actual=(SELECT jsonb_agg(value||jsonb_build_object('foreignKeys',(SELECT coalesce(jsonb_agg(fk ORDER BY fk->>'definition'),'[]'::jsonb) FROM jsonb_array_elements(value->'foreignKeys') fk)) ORDER BY value->>'table') FROM jsonb_array_elements(identity.retention_schema()));
EXCEPTION WHEN OTHERS THEN PERFORM set_config('search_path',old_path,true); RAISE;
END $$;
CREATE FUNCTION identity.retention_presence(descriptor jsonb,subject uuid) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE present boolean; predicate text:=descriptor->>'subjectScope';
BEGIN
 IF predicate IS NULL THEN RETURN NULL; END IF;
 -- Both relation and predicate come exclusively from the immutable migration snapshot.
 EXECUTE 'SELECT EXISTS(SELECT 1 FROM '||(descriptor->>'table')||' AS row WHERE '||replace(predicate,':userId','$1')||')' INTO present USING subject;
 RETURN present;
END $$;
CREATE FUNCTION identity.retention_record_digest(r identity.data_retention_records) RETURNS text LANGUAGE sql STABLE AS $$
 SELECT encode(sha256(convert_to(((to_jsonb(r)-'created_at'-'lease_expires_at')||jsonb_build_object(
  'createdAtEpoch',extract(epoch FROM r.created_at),'leaseExpiresAtEpoch',extract(epoch FROM r.lease_expires_at),
  'productEpoch',root.product_epoch,'accountVersion',root.account_version,'commandId',root.command_id,'requestId',root.request_id))::text,'UTF8')),'hex')
 FROM identity.account_deletion_records root WHERE root.id=r.deletion_record_id $$;
CREATE FUNCTION identity.retention_record_valid(r identity.data_retention_records) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE descriptor jsonb; root identity.account_deletion_records; a platform.audit_logs;
BEGIN
 SELECT value INTO descriptor FROM jsonb_array_elements(identity.retention_descriptors()) WHERE value->>'table'=r.retained_data_type;
 SELECT * INTO root FROM identity.account_deletion_records WHERE id=r.deletion_record_id;
 SELECT * INTO a FROM platform.audit_logs WHERE id=r.audit_id;
 RETURN coalesce(descriptor IS NOT NULL AND root.id IS NOT NULL AND r.user_id=root.user_id
  AND r.classification=descriptor->>'classification' AND r.disposition=descriptor->>'action' AND r.legal_or_safety_reason=descriptor->>'purpose'
  AND r.access_policy=CASE WHEN descriptor->>'classification'='reference' THEN 'reference_only' ELSE 'purpose_restricted' END
  AND r.policy_status=CASE WHEN descriptor->>'releasePolicy'='approval_required' THEN 'pending_approval' ELSE 'not_applicable' END
  AND r.retention_expires_at IS NULL AND r.indefinite_reason IS NULL AND r.deleted_at IS NULL
  AND (descriptor->>'subjectScope' IS NOT NULL OR r.observed_present IS NULL)
  AND r.registry_hash=identity.retention_registry_hash() AND r.created_at>=root.requested_at AND r.created_at<=clock_timestamp()
  AND isfinite(r.created_at) AND isfinite(r.lease_expires_at) AND r.created_at<r.lease_expires_at
  AND r.transaction_id~'^[1-9][0-9]{0,19}$' AND r.lease_generation>0
  AND a.category='account' AND a.event_type='account.deletion-retention-recorded.v1' AND a.actor_type='system'
  AND a.actor_user_id IS NULL AND a.actor_admin_id IS NULL AND a.subject_type='account_deletion' AND a.subject_id=root.id
  AND a.result_code='retention_recorded' AND a.metadata_schema_version=1
  AND a.metadata=jsonb_build_object('retentionRecordId',r.id,'resource',r.retained_data_type,'registryHash',r.registry_hash,'policyStatus',r.policy_status,'proofHash',identity.retention_record_digest(r))
  AND a.command_id=root.command_id AND a.request_id=root.request_id AND a.occurred_at=r.created_at,false);
END $$;
CREATE FUNCTION identity.guard_retention_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'retention release disabled pending policy approval' USING ERRCODE='55000'; END IF;
 IF identity.retention_record_valid(NEW) IS NOT TRUE OR NEW.transaction_id<>pg_current_xact_id()::text
  OR NOT EXISTS(SELECT 1 FROM identity.account_deletion_records r JOIN identity.account_deletion_work w ON w.deletion_record_id=r.id
   JOIN identity.accounts a ON a.user_id=r.user_id WHERE r.id=NEW.deletion_record_id AND r.phase='retention_manifest' AND r.checkpoint_version=6
   AND w.phase=r.phase AND w.checkpoint_version=r.checkpoint_version AND w.lease_owner=NEW.lease_owner AND w.lease_generation=NEW.lease_generation
   AND w.lease_expires_at=NEW.lease_expires_at AND w.lease_expires_at>clock_timestamp()
   AND a.state='deleted' AND a.version=r.account_version AND a.product_epoch=r.product_epoch AND r.completed_at IS NULL) THEN
  RAISE EXCEPTION 'retention manifest fence invalid' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER retention_record_guard BEFORE INSERT OR UPDATE OR DELETE ON identity.data_retention_records FOR EACH ROW EXECUTE FUNCTION identity.guard_retention_record();
CREATE FUNCTION identity.require_retention_record() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r identity.data_retention_records;
BEGIN
 IF TG_TABLE_NAME='audit_logs' THEN
  IF NEW.event_type<>'account.deletion-retention-recorded.v1' THEN RETURN NULL; END IF;
  SELECT * INTO r FROM identity.data_retention_records WHERE audit_id=NEW.id;
 ELSE SELECT * INTO r FROM identity.data_retention_records WHERE id=NEW.id; END IF;
 IF r.id IS NULL OR identity.retention_record_valid(r) IS NOT TRUE OR r.observed_present IS DISTINCT FROM identity.retention_presence((SELECT value FROM jsonb_array_elements(identity.retention_descriptors()) WHERE value->>'table'=r.retained_data_type),r.user_id) OR r.transaction_id<>pg_current_xact_id()::text OR clock_timestamp()>=r.lease_expires_at THEN
  RAISE EXCEPTION 'retention manifest required write missing or lease expired' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER retention_record_required AFTER INSERT ON identity.data_retention_records DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION identity.require_retention_record();
CREATE CONSTRAINT TRIGGER retention_audit_required AFTER INSERT ON platform.audit_logs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION identity.require_retention_record();
CREATE FUNCTION identity.record_retention_batch(root_id uuid,subject uuid,worker uuid,generation integer) RETURNS integer LANGUAGE plpgsql AS $$
DECLARE root identity.account_deletion_records; job identity.account_deletion_work; descriptor jsonb; r identity.data_retention_records; written integer:=0; affected integer;
BEGIN
 PERFORM id FROM identity.users WHERE id=subject FOR NO KEY UPDATE;
 PERFORM user_id FROM identity.accounts WHERE user_id=subject FOR UPDATE;
 SELECT * INTO root FROM identity.account_deletion_records WHERE id=root_id AND user_id=subject FOR UPDATE;
 SELECT * INTO job FROM identity.account_deletion_work WHERE deletion_record_id=root_id FOR UPDATE;
 IF root.id IS NULL OR root.phase<>'retention_manifest' OR root.checkpoint_version<>6 OR root.completed_at IS NOT NULL
  OR job.phase<>root.phase OR job.checkpoint_version<>root.checkpoint_version OR job.lease_owner IS DISTINCT FROM worker
  OR job.lease_generation IS DISTINCT FROM generation OR job.lease_expires_at IS NULL OR job.lease_expires_at<=clock_timestamp()
  OR NOT EXISTS(SELECT 1 FROM identity.accounts WHERE user_id=subject AND state='deleted' AND version=root.account_version AND product_epoch=root.product_epoch)
  OR identity.retention_catalog_valid() IS NOT TRUE OR identity.deletion_ephemeral_blocker(root_id,subject) IS NOT NULL THEN
  RAISE EXCEPTION 'retention manifest conflict' USING ERRCODE='40001'; END IF;
 FOR descriptor IN SELECT value FROM jsonb_array_elements(identity.retention_descriptors()) WHERE NOT EXISTS(
  SELECT 1 FROM identity.data_retention_records existing WHERE existing.deletion_record_id=root_id AND existing.retained_data_type=value->>'table') ORDER BY value->>'table' LIMIT 10 LOOP
  r.id:=gen_random_uuid(); r.user_id:=subject; r.deletion_record_id:=root_id; r.retained_data_type:=descriptor->>'table';
  r.classification:=descriptor->>'classification'; r.disposition:=descriptor->>'action'; r.legal_or_safety_reason:=descriptor->>'purpose';
  r.access_policy:=CASE WHEN r.classification='reference' THEN 'reference_only' ELSE 'purpose_restricted' END;
  r.policy_status:=CASE WHEN descriptor->>'releasePolicy'='approval_required' THEN 'pending_approval' ELSE 'not_applicable' END;
  r.retention_expires_at:=NULL; r.indefinite_reason:=NULL; r.deleted_at:=NULL;
  r.observed_present:=identity.retention_presence(descriptor,subject); r.registry_hash:=identity.retention_registry_hash();
  r.created_at:=clock_timestamp(); r.audit_id:=gen_random_uuid(); r.lease_owner:=worker; r.lease_generation:=generation;
  r.lease_expires_at:=job.lease_expires_at; r.transaction_id:=pg_current_xact_id()::text;
  INSERT INTO platform.audit_logs(id,category,event_type,actor_type,actor_user_id,actor_admin_id,subject_type,subject_id,result_code,metadata_schema_version,metadata,command_id,request_id,occurred_at)
  VALUES(r.audit_id,'account','account.deletion-retention-recorded.v1','system',NULL,NULL,'account_deletion',root_id,'retention_recorded',1,
   jsonb_build_object('retentionRecordId',r.id,'resource',r.retained_data_type,'registryHash',r.registry_hash,'policyStatus',r.policy_status,'proofHash',identity.retention_record_digest(r)),root.command_id,root.request_id,r.created_at);
  GET DIAGNOSTICS affected=ROW_COUNT; IF affected<>1 THEN RAISE EXCEPTION 'retention audit missing' USING ERRCODE='23514'; END IF;
  INSERT INTO identity.data_retention_records SELECT r.*;
  GET DIAGNOSTICS affected=ROW_COUNT; IF affected<>1 THEN RAISE EXCEPTION 'retention record missing' USING ERRCODE='23514'; END IF;
  written:=written+1;
 END LOOP;
 RETURN written;
END $$;
CREATE FUNCTION identity.deletion_retention_blocker(root_id uuid,subject uuid) RETURNS text LANGUAGE plpgsql AS $$
DECLARE descriptor jsonb; r identity.data_retention_records;
BEGIN
 IF identity.retention_catalog_valid() IS NOT TRUE THEN RETURN 'catalog'; END IF;
 IF identity.deletion_ephemeral_blocker(root_id,subject) IS NOT NULL THEN RETURN 'ephemeral'; END IF;
 FOR descriptor IN SELECT value FROM jsonb_array_elements(identity.retention_descriptors()) LOOP
  SELECT * INTO r FROM identity.data_retention_records WHERE deletion_record_id=root_id AND user_id=subject AND retained_data_type=descriptor->>'table';
  IF r.id IS NULL OR identity.retention_record_valid(r) IS NOT TRUE THEN RETURN 'manifest'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM identity.data_retention_records WHERE deletion_record_id=root_id AND NOT identity.retention_record_valid(data_retention_records)) THEN RETURN 'manifest'; END IF;
 RETURN NULL;
END $$;
CREATE OR REPLACE FUNCTION identity.guard_deletion_phase_receipt() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'deletion phase receipt requires controlled release' USING ERRCODE='55000';
  END IF;
  IF NEW.completed_phase='retention_manifest' AND identity.deletion_retention_blocker(NEW.deletion_record_id,(SELECT user_id FROM identity.account_deletion_records WHERE id=NEW.deletion_record_id)) IS NOT NULL THEN RAISE EXCEPTION 'retention verification incomplete' USING ERRCODE='23514'; END IF;
  IF NEW.completed_phase='ephemeral_access' AND (identity.deletion_ephemeral_blocker(NEW.deletion_record_id,(SELECT user_id FROM identity.account_deletion_records WHERE id=NEW.deletion_record_id)) IS NOT NULL OR NOT identity.ephemeral_reconciliation_valid(NEW.deletion_record_id,NEW.verified_at)) THEN RAISE EXCEPTION 'ephemeral verification incomplete' USING ERRCODE='23514'; END IF;
  IF NEW.completed_phase='media_objects' AND identity.deletion_media_blocker(NEW.deletion_record_id,(SELECT user_id FROM identity.account_deletion_records WHERE id=NEW.deletion_record_id)) IS NOT NULL THEN RAISE EXCEPTION 'media verification incomplete' USING ERRCODE='23514'; END IF;
  IF NEW.completed_phase='product_data' AND identity.deletion_product_blocker(NEW.deletion_record_id,(SELECT user_id FROM identity.account_deletion_records WHERE id=NEW.deletion_record_id)) IS NOT NULL THEN RAISE EXCEPTION 'product verification incomplete' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS (SELECT 1 FROM identity.account_deletion_records record
    JOIN identity.account_deletion_work work ON work.deletion_record_id=record.id
    JOIN identity.accounts account ON account.user_id=record.user_id
    WHERE record.id=NEW.deletion_record_id AND record.phase=NEW.completed_phase
      AND record.checkpoint_version=NEW.from_checkpoint_version AND record.checklist_version=NEW.checklist_version
      AND work.phase=record.phase AND work.checkpoint_version=record.checkpoint_version
      AND work.lease_owner=NEW.lease_owner AND work.lease_generation=NEW.lease_generation
      AND work.lease_expires_at=NEW.lease_expires_at AND work.lease_expires_at>clock_timestamp()
      AND account.state='deleted' AND account.version=record.account_version
      AND EXISTS (SELECT 1 FROM platform.user_counters WHERE user_id=record.user_id AND pending_nakh_count=0)
      AND NEW.verified_at>=record.requested_at AND NEW.verified_at<=clock_timestamp()
      AND NOT identity.deletion_has_open_shared_scopes(record.user_id)
      AND (NEW.completed_phase='shared_closure' OR (record.shared_closed_at IS NOT NULL
        AND EXISTS(SELECT 1 FROM identity.account_deletion_phase_receipts prior
          WHERE prior.deletion_record_id=record.id AND prior.completed_phase='shared_closure'
            AND prior.verified_at=record.shared_closed_at)
        AND identity.deletion_evidence_blocker(record.id,record.user_id) IS NULL))) THEN
    RAISE EXCEPTION 'deletion phase receipt lacks verified fence' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION identity.require_deletion_phase_receipt() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM identity.account_deletion_records record
    JOIN identity.account_deletion_work work ON work.deletion_record_id=record.id
    JOIN identity.accounts account ON account.user_id=record.user_id
    JOIN platform.audit_logs audit ON audit.id=NEW.audit_id
    JOIN platform.outbox_events event ON event.id=NEW.event_id
    WHERE record.id=NEW.deletion_record_id AND record.phase=NEW.next_phase
      AND record.checkpoint_version=NEW.next_checkpoint_version
      AND ((NEW.completed_phase='shared_closure' AND record.shared_closed_at=NEW.verified_at)
        OR (NEW.completed_phase='evidence_capture' AND EXISTS(SELECT 1 FROM identity.account_deletion_phase_receipts prior
          WHERE prior.deletion_record_id=record.id AND prior.completed_phase='shared_closure' AND prior.verified_at=record.shared_closed_at)
          AND identity.deletion_evidence_blocker(record.id,record.user_id) IS NULL)
        OR (NEW.completed_phase='retention_manifest' AND EXISTS(SELECT 1 FROM identity.account_deletion_phase_receipts prior WHERE prior.deletion_record_id=record.id AND prior.completed_phase='ephemeral_access'))
        OR (NEW.completed_phase='ephemeral_access' AND EXISTS(SELECT 1 FROM identity.account_deletion_phase_receipts prior WHERE prior.deletion_record_id=record.id AND prior.completed_phase='media_objects'))
        OR (NEW.completed_phase='media_objects' AND EXISTS(SELECT 1 FROM identity.account_deletion_phase_receipts prior WHERE prior.deletion_record_id=record.id AND prior.completed_phase='product_data'))
        OR (NEW.completed_phase='product_data' AND EXISTS(SELECT 1 FROM identity.account_deletion_phase_receipts prior WHERE prior.deletion_record_id=record.id AND prior.completed_phase='evidence_capture')))
      AND (NEW.completed_phase<>'retention_manifest' OR identity.deletion_retention_blocker(record.id,record.user_id) IS NULL)
      AND (NEW.completed_phase<>'ephemeral_access' OR (identity.deletion_ephemeral_blocker(record.id,record.user_id) IS NULL AND identity.ephemeral_reconciliation_valid(record.id,NEW.verified_at)))
      AND (NEW.completed_phase<>'media_objects' OR identity.deletion_media_blocker(record.id,record.user_id) IS NULL)
      AND (NEW.completed_phase<>'product_data' OR identity.deletion_product_blocker(record.id,record.user_id) IS NULL)
      AND record.product_purged_at IS NULL
      AND record.checklist_version=NEW.checklist_version AND record.purge_started_at IS NOT NULL
      AND record.last_error_code IS NULL AND NOT record.reactivation_allowed AND record.completed_at IS NULL
      AND work.phase=record.phase AND work.checkpoint_version=record.checkpoint_version
      AND work.lease_generation=NEW.lease_generation AND work.lease_owner IS NULL AND work.lease_expires_at IS NULL
      AND work.available_at=NEW.verified_at AND work.last_error_code IS NULL
      AND account.state='deleted' AND account.version=record.account_version
      AND EXISTS (SELECT 1 FROM platform.user_counters WHERE user_id=record.user_id AND pending_nakh_count=0)
      AND clock_timestamp()<NEW.lease_expires_at AND NOT identity.deletion_has_open_shared_scopes(record.user_id)
      AND audit.category='account' AND audit.event_type='account.deletion-phase-completed.v1'
      AND audit.actor_type='system' AND audit.actor_user_id IS NULL AND audit.actor_admin_id IS NULL
      AND audit.subject_type='account_deletion' AND audit.subject_id=record.id AND audit.result_code='phase_completed'
      AND audit.metadata_schema_version=1 AND audit.metadata=jsonb_build_object('phase',NEW.completed_phase,'checkpointVersion',NEW.from_checkpoint_version)
      AND audit.command_id=record.command_id AND audit.request_id=record.request_id AND audit.occurred_at=NEW.verified_at
      AND event.aggregate_type='account_deletion' AND event.aggregate_id=record.id
      AND event.event_type='account.deletion-phase-completed.v1' AND event.schema_version=1
      AND event.payload=jsonb_build_object('deletionRecordId',record.id,'completedPhase',NEW.completed_phase,'nextPhase',NEW.next_phase,'checkpointVersion',NEW.next_checkpoint_version)
      AND event.correlation_id=record.request_id AND event.causation_id=record.command_id AND event.occurred_at=NEW.verified_at) THEN
    RAISE EXCEPTION 'deletion phase completion chain incomplete' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION identity.guard_deletion_checkpoint() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'deletion history requires controlled release' USING ERRCODE='55000';
  END IF;
  IF ROW(NEW.id,NEW.user_id,NEW.confirmation_id,NEW.account_version,NEW.history_id,NEW.audit_id,
      NEW.event_id,NEW.command_id,NEW.request_id,NEW.checklist_version,NEW.requested_at,NEW.safety_bar)
    IS DISTINCT FROM ROW(OLD.id,OLD.user_id,OLD.confirmation_id,OLD.account_version,OLD.history_id,OLD.audit_id,
      OLD.event_id,OLD.command_id,OLD.request_id,OLD.checklist_version,OLD.requested_at,OLD.safety_bar)
    OR OLD.phase='completed' OR NEW.reactivation_allowed
    OR NEW.product_purged_at IS DISTINCT FROM OLD.product_purged_at
    OR NEW.completed_at IS DISTINCT FROM OLD.completed_at
    OR (OLD.purge_started_at IS NOT NULL AND NEW.purge_started_at IS DISTINCT FROM OLD.purge_started_at)
    OR (NEW.purge_started_at IS NOT NULL AND (NEW.purge_started_at<NEW.requested_at OR NEW.purge_started_at>clock_timestamp())) THEN
    RAISE EXCEPTION 'deletion checkpoint transition invalid' USING ERRCODE='55000';
  END IF;
  IF NEW.phase=OLD.phase THEN
    IF NEW.checkpoint_version<>OLD.checkpoint_version OR NEW.shared_closed_at IS DISTINCT FROM OLD.shared_closed_at THEN
      RAISE EXCEPTION 'deletion checkpoint milestone requires receipt' USING ERRCODE='55000';
    END IF;
  ELSIF NOT ((OLD.phase='shared_closure' AND NEW.phase='evidence_capture'
      AND OLD.checkpoint_version=1 AND NEW.checkpoint_version=2)
      OR (OLD.phase='evidence_capture' AND NEW.phase='product_data'
        AND OLD.checkpoint_version=2 AND NEW.checkpoint_version=3)
      OR (OLD.phase='product_data' AND NEW.phase='media_objects' AND OLD.checkpoint_version=3 AND NEW.checkpoint_version=4)
      OR (OLD.phase='media_objects' AND NEW.phase='ephemeral_access' AND OLD.checkpoint_version=4 AND NEW.checkpoint_version=5)
      OR (OLD.phase='ephemeral_access' AND NEW.phase='retention_manifest' AND OLD.checkpoint_version=5 AND NEW.checkpoint_version=6)
      OR (OLD.phase='retention_manifest' AND NEW.phase='verification' AND OLD.checkpoint_version=6 AND NEW.checkpoint_version=7))
    OR NOT EXISTS (SELECT 1 FROM identity.account_deletion_phase_receipts receipt
      WHERE receipt.deletion_record_id=NEW.id AND receipt.completed_phase=OLD.phase
        AND receipt.next_phase=NEW.phase AND receipt.from_checkpoint_version=OLD.checkpoint_version
        AND receipt.next_checkpoint_version=NEW.checkpoint_version
        AND ((OLD.phase='shared_closure' AND NEW.shared_closed_at=receipt.verified_at)
          OR (OLD.phase IN('evidence_capture','product_data','media_objects','ephemeral_access','retention_manifest') AND NEW.shared_closed_at IS NOT DISTINCT FROM OLD.shared_closed_at))) THEN
    RAISE EXCEPTION 'deletion checkpoint requires verified executor' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION identity.guard_deletion_work_lease() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE at timestamptz := clock_timestamp();
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.phase<>'shared_closure' OR NEW.checkpoint_version<>1 OR NEW.lease_generation<>0
      OR NEW.attempt_count<>0 OR NEW.lease_owner IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_error_code IS NOT NULL THEN
      RAISE EXCEPTION 'deletion work admission invalid' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.deletion_record_id<>OLD.deletion_record_id OR OLD.phase='completed' THEN
    RAISE EXCEPTION 'deletion work identity invalid' USING ERRCODE='55000';
  END IF;
  IF NEW.phase<>OLD.phase OR NEW.checkpoint_version<>OLD.checkpoint_version THEN
    IF NOT ((OLD.phase='shared_closure' AND NEW.phase='evidence_capture' AND OLD.checkpoint_version=1 AND NEW.checkpoint_version=2)
      OR (OLD.phase='evidence_capture' AND NEW.phase='product_data' AND OLD.checkpoint_version=2 AND NEW.checkpoint_version=3)
      OR (OLD.phase='product_data' AND NEW.phase='media_objects' AND OLD.checkpoint_version=3 AND NEW.checkpoint_version=4)
      OR (OLD.phase='media_objects' AND NEW.phase='ephemeral_access' AND OLD.checkpoint_version=4 AND NEW.checkpoint_version=5)
      OR (OLD.phase='ephemeral_access' AND NEW.phase='retention_manifest' AND OLD.checkpoint_version=5 AND NEW.checkpoint_version=6)
      OR (OLD.phase='retention_manifest' AND NEW.phase='verification' AND OLD.checkpoint_version=6 AND NEW.checkpoint_version=7))
      OR NEW.lease_generation<>OLD.lease_generation OR NEW.attempt_count<>OLD.attempt_count
      OR NEW.lease_owner IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_error_code IS NOT NULL
      OR OLD.lease_owner IS NULL OR OLD.lease_expires_at<=at
      OR NOT EXISTS (SELECT 1 FROM identity.account_deletion_phase_receipts receipt
        WHERE receipt.deletion_record_id=OLD.deletion_record_id AND receipt.completed_phase=OLD.phase
          AND receipt.from_checkpoint_version=OLD.checkpoint_version AND receipt.next_phase=NEW.phase
          AND receipt.next_checkpoint_version=NEW.checkpoint_version AND receipt.lease_owner=OLD.lease_owner
          AND receipt.lease_generation=OLD.lease_generation AND receipt.lease_expires_at=OLD.lease_expires_at
          AND receipt.verified_at=NEW.available_at) THEN
      RAISE EXCEPTION 'deletion work phase requires verified executor' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.lease_generation<>OLD.lease_generation THEN
    IF NEW.lease_generation<>OLD.lease_generation+1 OR NEW.attempt_count<>OLD.attempt_count+1
      OR (OLD.lease_owner IS NOT NULL AND OLD.lease_expires_at>at)
      OR NEW.lease_owner IS NULL OR NEW.lease_expires_at<=at OR NEW.lease_expires_at>at+interval '120 seconds'
      OR NEW.available_at IS DISTINCT FROM OLD.available_at OR NEW.last_error_code IS DISTINCT FROM OLD.last_error_code THEN
      RAISE EXCEPTION 'deletion work acquisition invalid' USING ERRCODE='55000';
    END IF;
  ELSE
    IF NEW.attempt_count<>OLD.attempt_count
      OR (NEW.lease_owner IS NOT NULL AND NEW.lease_owner IS DISTINCT FROM OLD.lease_owner)
      OR (NEW.lease_owner IS NOT NULL AND (OLD.lease_expires_at<=at OR NEW.lease_expires_at<OLD.lease_expires_at
        OR NEW.lease_expires_at<=at OR NEW.lease_expires_at>at+interval '120 seconds'
        OR NEW.available_at IS DISTINCT FROM OLD.available_at OR NEW.last_error_code IS DISTINCT FROM OLD.last_error_code)) THEN
      RAISE EXCEPTION 'deletion work lease mutation invalid' USING ERRCODE='55000';
    END IF;
  END IF;
  RETURN NEW;
END $$;

ALTER TABLE identity.account_deletion_phase_receipts DROP CONSTRAINT deletion_phase_receipt_transition_check,
 ADD CONSTRAINT deletion_phase_receipt_transition_check CHECK(
  (completed_phase='shared_closure' AND from_checkpoint_version=1 AND next_phase='evidence_capture' AND next_checkpoint_version=2)
  OR (completed_phase='evidence_capture' AND from_checkpoint_version=2 AND next_phase='product_data' AND next_checkpoint_version=3)
  OR (completed_phase='product_data' AND from_checkpoint_version=3 AND next_phase='media_objects' AND next_checkpoint_version=4)
  OR (completed_phase='media_objects' AND from_checkpoint_version=4 AND next_phase='ephemeral_access' AND next_checkpoint_version=5)
  OR (completed_phase='ephemeral_access' AND from_checkpoint_version=5 AND next_phase='retention_manifest' AND next_checkpoint_version=6)
  OR (completed_phase='retention_manifest' AND from_checkpoint_version=6 AND next_phase='verification' AND next_checkpoint_version=7));

CREATE FUNCTION identity.finish_deletion_retention_phase(deletion_id uuid, subject uuid, worker uuid, generation integer, checkpoint integer)
RETURNS TABLE(phase text, checkpoint_version integer, replayed boolean, waiting_for text) LANGUAGE plpgsql AS $$
DECLARE root identity.account_deletion_records; job identity.account_deletion_work;
  receipt identity.account_deletion_phase_receipts; at timestamptz; audit uuid; event uuid; blocker text; writes integer;
BEGIN
  IF deletion_id IS NULL OR subject IS NULL OR worker IS NULL OR generation IS NULL OR generation<1 OR checkpoint IS DISTINCT FROM 6 THEN
    RAISE EXCEPTION 'deletion work conflict' USING ERRCODE='40001';
  END IF;
  PERFORM id FROM identity.users WHERE id=subject FOR NO KEY UPDATE;
  PERFORM user_id FROM identity.accounts WHERE user_id=subject FOR UPDATE;
  SELECT * INTO root FROM identity.account_deletion_records WHERE id=deletion_id AND user_id=subject FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'deletion work conflict' USING ERRCODE='40001'; END IF;
  SELECT * INTO job FROM identity.account_deletion_work WHERE deletion_record_id=deletion_id FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM identity.accounts WHERE user_id=subject AND state='deleted' AND version=root.account_version AND product_epoch=root.product_epoch) THEN
    RAISE EXCEPTION 'deletion work conflict' USING ERRCODE='40001';
  END IF;
  SELECT * INTO receipt FROM identity.account_deletion_phase_receipts WHERE deletion_record_id=deletion_id AND completed_phase='retention_manifest';
  IF FOUND THEN
    IF receipt.lease_owner<>worker OR receipt.lease_generation<>generation OR receipt.from_checkpoint_version<>checkpoint THEN
      RAISE EXCEPTION 'deletion work conflict' USING ERRCODE='40001';
    END IF;
    RETURN QUERY SELECT receipt.next_phase,receipt.next_checkpoint_version,true,NULL::text; RETURN;
  END IF;
  at:=clock_timestamp();
  IF root.phase<>'retention_manifest' OR root.checkpoint_version<>6 OR checkpoint<>6
    OR job.phase<>root.phase OR job.checkpoint_version<>root.checkpoint_version
    OR job.lease_owner IS DISTINCT FROM worker OR job.lease_generation<>generation OR job.lease_expires_at IS NULL OR job.lease_expires_at<=at
    OR NOT EXISTS (SELECT 1 FROM platform.user_counters WHERE user_id=subject AND pending_nakh_count=0)
    OR identity.deletion_has_open_shared_scopes(subject) THEN
    RAISE EXCEPTION 'deletion work conflict' USING ERRCODE='40001';
  END IF;
  blocker:=identity.deletion_retention_blocker(deletion_id,subject);
  IF blocker IS NOT NULL THEN RETURN QUERY SELECT 'retention_manifest'::text,6,false,blocker; RETURN; END IF;
  audit:=gen_random_uuid(); event:=gen_random_uuid();
  INSERT INTO platform.audit_logs(id,category,event_type,actor_type,actor_user_id,actor_admin_id,subject_type,subject_id,result_code,
    metadata_schema_version,metadata,command_id,request_id,occurred_at)
  VALUES(audit,'account','account.deletion-phase-completed.v1','system',NULL,NULL,'account_deletion',deletion_id,'phase_completed',1,
    jsonb_build_object('phase','retention_manifest','checkpointVersion',6),root.command_id,root.request_id,at);
  GET DIAGNOSTICS writes=ROW_COUNT; IF writes<>1 THEN RAISE EXCEPTION 'retention checkpoint audit missing' USING ERRCODE='23514'; END IF;
  INSERT INTO platform.outbox_events(id,aggregate_type,aggregate_id,event_type,schema_version,payload,occurred_at,available_at,correlation_id,causation_id)
  VALUES(event,'account_deletion',deletion_id,'account.deletion-phase-completed.v1',1,
    jsonb_build_object('deletionRecordId',deletion_id,'completedPhase','retention_manifest','nextPhase','verification','checkpointVersion',7),at,at,root.request_id,root.command_id);
  GET DIAGNOSTICS writes=ROW_COUNT; IF writes<>1 THEN RAISE EXCEPTION 'retention checkpoint event missing' USING ERRCODE='23514'; END IF;
  INSERT INTO identity.account_deletion_phase_receipts(deletion_record_id,completed_phase,from_checkpoint_version,next_phase,next_checkpoint_version,
    checklist_version,lease_owner,lease_generation,lease_expires_at,verified_at,audit_id,event_id)
  VALUES(deletion_id,'retention_manifest',6,'verification',7,root.checklist_version,worker,generation,job.lease_expires_at,at,audit,event);
  GET DIAGNOSTICS writes=ROW_COUNT; IF writes<>1 THEN RAISE EXCEPTION 'retention checkpoint receipt missing' USING ERRCODE='23514'; END IF;
  UPDATE identity.account_deletion_records SET phase='verification',checkpoint_version=7,last_error_code=NULL WHERE id=deletion_id;
  GET DIAGNOSTICS writes=ROW_COUNT; IF writes<>1 THEN RAISE EXCEPTION 'retention checkpoint root update missing' USING ERRCODE='23514'; END IF;
  UPDATE identity.account_deletion_work SET phase='verification',checkpoint_version=7,available_at=at,
    lease_owner=NULL,lease_expires_at=NULL,last_error_code=NULL WHERE deletion_record_id=deletion_id;
  GET DIAGNOSTICS writes=ROW_COUNT; IF writes<>1 THEN RAISE EXCEPTION 'retention checkpoint work update missing' USING ERRCODE='23514'; END IF;
  RETURN QUERY SELECT 'verification'::text,7,false,NULL::text;
END $$;

-- Manifest audits contain only reviewed descriptors and proof identifiers.
DO $$ DECLARE definition text; BEGIN
 SELECT pg_get_functiondef('platform.deletion_operational_blocker(uuid)'::regprocedure) INTO definition;
 IF position('AND NOT (' IN definition)=0 THEN RAISE EXCEPTION 'operational blocker shape changed'; END IF;
 definition:=replace(definition,'AND NOT (', $replacement$AND NOT (
  (audit.event_type='account.deletion-retention-recorded.v1' AND EXISTS(SELECT 1 FROM identity.data_retention_records r WHERE r.audit_id=audit.id AND identity.retention_record_valid(r))) OR $replacement$);
 EXECUTE definition;
END $$;
